-- Baseline schema for CoZagrac (hand-maintained; NOT generated by drizzle-kit).
--
-- Source of truth: live dev DB catalog dump (pg_indexes / pg_constraint /
-- information_schema.columns), October 2026. src/drizzle/schema.ts and the
-- commented-out 0000_special_mandroid.sql artifact are KNOWN to be stale here
-- (they claim sessions.user_id, missing defaults, wrong index operator
-- classes) - do not bootstrap from them.
--
-- Bootstrap order on a fresh database (all scripts in this folder):
--   1) createdb <db>
--   2) extensions.sql
--   3) THIS file
--   4) post_migrate.sql   (search_vector trigger - drizzle does not manage it)
--   5) grants.sql
--   6) verify.sql
--
-- Conventions: constraint/index names 1:1 with dev; NO explicit btree operator
-- classes (PG derives them from column types); all FKs ON DELETE CASCADE.
--
-- Client-agnostic plain SQL: run with psql -f OR paste into pgAdmin/QEditor.
-- Atomicity: everything runs in the explicit transaction below - on any error
-- the whole script rolls back.

BEGIN;
SET LOCAL search_path TO public;

-- ========================= users & auth =========================

CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- unique email: register pre-checks it (400 Email already exists); the
  -- constraint closes the concurrent-registration race. Steam-only users keep
  -- NULL which is exempt from uniqueness in PostgreSQL.
  email varchar,
  password_hash varchar,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_key UNIQUE (email)
);

CREATE TABLE user_providers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  provider varchar NOT NULL,
  provider_user_id varchar NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_providers_provider_provider_user_id_key UNIQUE (provider, provider_user_id)
);

-- column names are fixed by connect-pg-simple (sid/sess/expire); the table
-- must exist before first request - the store never creates it
CREATE TABLE sessions (
  sid varchar PRIMARY KEY,
  sess jsonb NOT NULL,
  expire timestamptz NOT NULL
);

-- ========================= game catalog =========================

CREATE TABLE game_info (
  steam_appid integer PRIMARY KEY,
  name varchar,
  short_description text,
  detailed_description text,
  about_the_game text,
  is_free boolean,
  required_age integer,
  platform_windows boolean,
  platform_mac boolean,
  platform_linux boolean,
  header_image varchar,
  capsule_image varchar,
  background varchar,
  website varchar,
  app_url varchar,
  release_coming_soon boolean,
  release_date text,
  price_currency varchar,
  price_initial integer,
  price_final integer,
  price_initial_formatted varchar,
  price_final_formatted varchar,
  price_discount_percent integer,
  pc_minimum text,
  pc_recommended text,
  mac_minimum text,
  mac_recommended text,
  linux_minimum text,
  linux_recommended text,
  search_vector tsvector,
  is_candidate boolean,
  review_tier varchar(1)
);

CREATE TABLE genres (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  steam_genre_id integer,
  name varchar
);

CREATE TABLE categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  steam_category_id integer,
  name varchar
);

CREATE TABLE tags (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  steam_tag_id integer,
  name varchar
);

-- ========================= junctions / media / reviews =========================

CREATE TABLE game_genres (
  steam_appid integer NOT NULL,
  genre_id uuid NOT NULL,
  PRIMARY KEY (steam_appid, genre_id)
);

CREATE TABLE game_categories (
  steam_appid integer NOT NULL,
  category_id uuid NOT NULL,
  PRIMARY KEY (steam_appid, category_id)
);

CREATE TABLE game_screenshots (
  steam_appid integer NOT NULL,
  screenshot_id integer NOT NULL,
  path_thumbnail varchar,
  path_full varchar,
  PRIMARY KEY (steam_appid, screenshot_id)
);

CREATE TABLE game_movies (
  steam_appid integer NOT NULL,
  movie_id integer NOT NULL,
  name varchar,
  thumbnail varchar,
  url varchar,
  PRIMARY KEY (steam_appid, movie_id)
);

CREATE TABLE game_publishers (
  steam_appid integer NOT NULL,
  publisher_id integer NOT NULL,
  name varchar,
  PRIMARY KEY (steam_appid, publisher_id)
);

CREATE TABLE game_reviews (
  steam_appid integer NOT NULL,
  recommendation_id integer NOT NULL,
  review text,
  voted_up boolean,
  votes_up integer,
  votes_funny integer,
  weighted_vote_score double precision,
  playtime_forever integer NOT NULL DEFAULT 0,
  steam_purchase boolean,
  comment_count integer,
  review_created date,
  language varchar(50),
  PRIMARY KEY (steam_appid, recommendation_id)
);

-- ========================= embeddings (pgvector) =========================

CREATE TABLE game_embeddings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  steam_appid integer NOT NULL,
  embedding vector(1536) NOT NULL,
  model_name varchar,
  created_at timestamptz DEFAULT now(),
  embedding_version varchar(32) NOT NULL
);

CREATE TABLE user_embeddings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  embedding vector(1536) NOT NULL,
  model_name varchar,
  created_at timestamptz DEFAULT now(),
  embedding_version varchar(32) NOT NULL
);

-- manual profile basis: user-picked favorite games (also excluded from
-- recommendation results); steam-library users may keep this empty
CREATE TABLE user_favorite_games (
  user_id uuid NOT NULL,
  steam_appid integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, steam_appid)
);

-- ========================= user preferences (unused by code, kept for parity) =========================

CREATE TABLE user_genres (
  user_id uuid NOT NULL,
  genre_id uuid NOT NULL,
  PRIMARY KEY (user_id, genre_id)
);

CREATE TABLE user_categories (
  user_id uuid NOT NULL,
  category_id uuid NOT NULL,
  PRIMARY KEY (user_id, category_id)
);

CREATE TABLE user_tags (
  user_id uuid NOT NULL,
  tag_id uuid NOT NULL,
  PRIMARY KEY (user_id, tag_id)
);

-- ========================= taxonomy unique lookups =========================

ALTER TABLE genres ADD CONSTRAINT uq_genres_steam_genre_id UNIQUE (steam_genre_id);
ALTER TABLE genres ADD CONSTRAINT genres_name_key UNIQUE (name);
ALTER TABLE categories ADD CONSTRAINT uq_categories_steam_category_id UNIQUE (steam_category_id);
ALTER TABLE categories ADD CONSTRAINT categories_name_key UNIQUE (name);
ALTER TABLE tags ADD CONSTRAINT uq_tags_steam_tag_id UNIQUE (steam_tag_id);
ALTER TABLE tags ADD CONSTRAINT tags_name_key UNIQUE (name);

-- ========================= foreign keys (all CASCADE, names 1:1 with dev) =========================

ALTER TABLE user_providers ADD CONSTRAINT user_providers_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

ALTER TABLE game_genres ADD CONSTRAINT game_genres_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;
ALTER TABLE game_genres ADD CONSTRAINT game_genres_genre_id_fkey
  FOREIGN KEY (genre_id) REFERENCES genres(id) ON DELETE CASCADE;

ALTER TABLE game_categories ADD CONSTRAINT game_categories_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;
ALTER TABLE game_categories ADD CONSTRAINT game_categories_category_id_fkey
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE;

ALTER TABLE game_screenshots ADD CONSTRAINT game_screenshots_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE game_movies ADD CONSTRAINT game_movies_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE game_publishers ADD CONSTRAINT game_publishers_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE game_reviews ADD CONSTRAINT game_reviews_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE game_embeddings ADD CONSTRAINT game_embeddings_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE user_embeddings ADD CONSTRAINT user_embeddings_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

ALTER TABLE user_favorite_games ADD CONSTRAINT user_favorite_games_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE user_favorite_games ADD CONSTRAINT user_favorite_games_steam_appid_fkey
  FOREIGN KEY (steam_appid) REFERENCES game_info(steam_appid) ON DELETE CASCADE;

ALTER TABLE user_genres ADD CONSTRAINT user_genres_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE user_genres ADD CONSTRAINT user_genres_genre_id_fkey
  FOREIGN KEY (genre_id) REFERENCES genres(id) ON DELETE CASCADE;

ALTER TABLE user_categories ADD CONSTRAINT user_categories_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE user_categories ADD CONSTRAINT user_categories_category_id_fkey
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE;

ALTER TABLE user_tags ADD CONSTRAINT user_tags_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE user_tags ADD CONSTRAINT user_tags_tag_id_fkey
  FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;

-- ========================= indexes (names 1:1 with dev, no operator classes) =========================

CREATE INDEX idx_sessions_expire ON sessions (expire);

CREATE INDEX idx_game_info_is_candidate ON game_info (is_candidate);
CREATE INDEX idx_game_info_is_free ON game_info (is_free);
CREATE INDEX idx_game_info_release_date ON game_info (release_date);
-- GIN on tsvector requires its (only) operator class; explicit on purpose
CREATE INDEX idx_game_info_search_vector ON game_info USING gin (search_vector);

CREATE INDEX idx_game_genres_genre_id ON game_genres (genre_id);
CREATE INDEX idx_game_genres_steam_appid ON game_genres (steam_appid);

CREATE INDEX idx_game_categories_category_id ON game_categories (category_id);
CREATE INDEX idx_game_categories_steam_appid ON game_categories (steam_appid);

CREATE INDEX idx_game_screenshots_steam_appid ON game_screenshots (steam_appid);
CREATE INDEX idx_game_movies_steam_appid ON game_movies (steam_appid);
CREATE INDEX idx_game_publishers_steam_appid ON game_publishers (steam_appid);

CREATE INDEX idx_reviews_appid_created ON game_reviews (steam_appid, review_created DESC);
CREATE INDEX idx_reviews_appid_voted_up ON game_reviews (steam_appid, voted_up);
CREATE INDEX idx_reviews_appid_weighted ON game_reviews (steam_appid, weighted_vote_score DESC);

-- HNSW requires the vector operator class; explicit on purpose
CREATE INDEX idx_game_embeddings_steam_appid ON game_embeddings (steam_appid);
CREATE INDEX idx_game_embeddings_vector ON game_embeddings USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_game_embeddings_version ON game_embeddings (embedding_version);

CREATE INDEX idx_user_embeddings_user_id ON user_embeddings (user_id);
CREATE INDEX idx_user_embeddings_vector ON user_embeddings USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_user_embeddings_version ON user_embeddings (embedding_version);

-- user_id side is covered by the PK prefix (user_id, steam_appid)
CREATE INDEX idx_user_favorite_games_steam_appid ON user_favorite_games (steam_appid);

CREATE INDEX idx_user_genres_user_id ON user_genres (user_id);
CREATE INDEX idx_user_categories_user_id ON user_categories (user_id);
CREATE INDEX idx_user_tags_user_id ON user_tags (user_id);

-- ========================= view (kept out of active schema) =========================

-- Abandoned experiment: filtered a single game by name; unused by backend and
-- frontend (see drop_genre_names_for_game_view.sql). Definition from dev:
-- CREATE VIEW public.genre_names_for_game_view AS
--   SELECT steam_appid,
--          (SELECT array_agg(g.name ORDER BY g.name)
--             FROM game_genres gg
--             JOIN genres g ON g.id = gg.genre_id
--            WHERE gg.steam_appid = gi.steam_appid) AS genres
--     FROM game_info gi
--    WHERE name = 'Shadow of the Tomb Raider: Definitive Edition';

COMMIT;
